"""Netact ne integrator"""

from taf.ul.trs_e2e_fw.lib.ems.netact.netact_base import NetactBase


class Monitor(NetactBase):
    """Netact ne integrator"""
    def __init__(self):
        super(Monitor, self).__init__()

    def delete_object_from_monitor(self, **kwargs):
        """
        This keyword deletes object in Monitor. It uses /opt/oss/bin/nasdaclimx.sh to remove object from NASDA database.

        Parameters:

            dist_name (string) The distinguished name of the network element,
                e.g.: PLMN-PLMN/MRBTS-123456.
            alias (string) Name of execution context.
        Returns:
        Operation result

        Return type:
        bool
        """
        dist_name = kwargs['dist_name']
        alias = kwargs.pop('alias', 'default')

        return self.netact_factory.netact.delete_object_from_monitor(dist_name, alias=alias)
